mapper.select:
select cr_mission_template.title as title, cr_business_template.name as scene_name, cr_task.mission_template_id as resource_id, cr_task.update_time as time from cr_task inner join cr_mission_template on cr_task.mission_template_id = cr_mission_template.resource_id inner join cr_business_template on cr_mission_template.business_template_id = cr_business_template.resource_id where cr_task.user_id = #{userId} and cr_task.score is not null and cr_task.mission_template_id in
#{missionTemplateId}
order by cr_task.update_time desc
